+  [[0.5, 0, 0], [0.275, 0, 0.119]],
+  [[0.275, 0, 0.119], [-0.5, 0, 0.34]],
+  [[0.05, 0.067, 0], [-0.5, 0.101, 0]],
+  [[0.05, -0.067, 0], [-0.5, -0.101, 0]],
