+    const friendly = i < PER_SIDE, k = i % PER_SIDE;
+    const r = mix(seed, i);
+    const spread = (k - (PER_SIDE - 1) / 2) * 34;                 // a line abreast, 34 m apart
+    const depth = (k % 3) * 55;                                   // three ranks, so it reads as a formation
